            { "{0} min temu", "{0} min ago" },
            { "{0} h temu", "{0} h ago" },
            { "Znany jest tylko obwód, dokładne położenie nieznane.", "Only the region is known, the exact position is unknown." },
            { "Obserwacja, nie sygnał do schronienia.", "An observation, not a signal to take shelter." },
